import type { DigitalPlatform } from './digital-platform-model';
import type { ManufacturingSite } from './manufacturing-site-model';

export const PlatformDeploymentStatusKeyToLabel = {
  'OnTrack': 'On Track',
  'AtRisk': 'At Risk',
  'Delayed': 'Delayed'
} as const;
export type PlatformDeploymentStatusKey = keyof typeof PlatformDeploymentStatusKeyToLabel;

export interface PlatformDeployment {
  /**
   * @displayName Platform Deployment ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Platform Deployment Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  platformDeploymentName: string;
  /**
   * @displayName Briefing Note
   */
  briefingNote?: string;
  /**
   * @displayName Deployment Code
   * @validationRule Required for create/update operations
   */
  deploymentCode: string;
  /**
   * @displayName Digital Platform
   * @validationRule Required for create/update operations
   */
  digitalPlatform: Pick<DigitalPlatform, 'id' | 'digitalPlatformName'>;
  /**
   * @displayName Manufacturing Site
   * @validationRule Required for create/update operations
   */
  manufacturingSite: Pick<ManufacturingSite, 'id' | 'siteName'>;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: PlatformDeploymentStatusKey;
  /**
   * @displayName Target Go Live Date
   */
  targetGoLiveDate?: string;
}

export const _PlatformDeployment = 'PlatformDeployment' as const;